        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string sourceFingerprint, Func<SecurityModel> create)
        {
            Ensure(ctx); SecurityModel existing = Store.Models.FirstOrDefault(x => x != null && Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId) && Eq(x.SourceFingerprint, sourceFingerprint)); if (existing == null) { existing = create(); existing.Id = Id("security-model"); existing.SourceKind = sourceKind; existing.SourceId = sourceId; existing.SourceFingerprint = sourceFingerprint; existing.CreatedUtc = existing.UpdatedUtc = Now(); Store.Models.Insert(0, existing); Save(ctx); AppendLedger(ctx, "SOURCE_PROJECTION", existing.Id, sourceKind + " source projected without upstream mutation.", SecurityKernel.Fingerprint(existing), sourceFingerprint); }
            OpenModel(owner, ctx, existing, index);
        }

        private static void OpenModels(Window owner, DeepSystemsContext ctx) { Ensure(ctx); OpenSelectable(owner, "FORTRESS REGISTRY", Store.Models.Cast<object>().ToList(), "Double-click a retained security civilization. Source projection is referential; no upstream object is modified.", delegate(object x) { OpenModel(owner, ctx, x as SecurityModel, WorldKernel.ExternalIndex(ctx, false)); }); }
        private static void OpenModel(Window owner, DeepSystemsContext ctx, SecurityModel m, WorldIndex index)
        {
            if (m == null) return; Window w = W(owner, "YOMI · SECURITY MODEL · " + (m.Name ?? m.Id), 1460, 900); DockPanel root = Shell(m.Name ?? "SECURITY MODEL", m.Description + "\nFingerprint " + SecurityKernel.Fingerprint(m) + "   ·   source " + (m.SourceKind ?? "NATIVE") + "/" + (m.SourceId ?? "∅")); WrapPanel actions = new WrapPanel();
            actions.Children.Add(Btn("ASSETS", delegate { OpenCollection(w, "ASSETS", m.Assets.Cast<object>().ToList(), "Crown jewels, owners, dependencies and CIA-value criticality."); })); actions.Children.Add(Btn("IDENTITIES", delegate { OpenCollection(w, "IDENTITIES", m.Identities.Cast<object>().ToList(), "Subjects, groups, factors, privilege and lifecycle."); })); actions.Children.Add(Btn("POLICY", delegate { OpenCollection(w, "PERMISSIONS", m.Permissions.Cast<object>().ToList(), "Explicit allow and deny grants; deny overrides and default deny are kernel invariants."); })); actions.Children.Add(Btn("THREATS", delegate { List<object> x = m.Threats.Cast<object>().ToList(); x.AddRange(m.Weaknesses.Cast<object>()); x.AddRange(m.AttackSteps.Cast<object>()); OpenCollection(w, "SYNTHETIC THREAT MODEL", x, "Abstract defensive state transitions only; no live procedure or target authority."); })); actions.Children.Add(Btn("CONTROLS", delegate { OpenCollection(w, "CONTROLS", m.Controls.Cast<object>().ToList(), "Prevent, detect, respond, recover and govern layers."); })); actions.Children.Add(Btn("VALIDATE MODEL", delegate { OpenCollection(w, "MODEL VALIDATION", SecurityKernel.Validate(m).Cast<object>().ToList(), "Referential integrity, bounds, policy invariants, crown-jewel detection and reference-only safety."); })); actions.Children.Add(Btn("FORK", delegate { ForkSpecific(w, ctx, m); })); DockPanel.SetDock(actions, Dock.Top); root.Children.Add(actions); List<object> rows = new List<object>(); rows.AddRange(m.Zones.Cast<object>()); rows.AddRange(m.Assets.Cast<object>()); rows.AddRange(m.Identities.Cast<object>()); rows.AddRange(m.SecretReferences.Cast<object>()); rows.AddRange(m.Permissions.Cast<object>()); rows.AddRange(m.TrustRelations.Cast<object>()); rows.AddRange(m.Interfaces.Cast<object>()); rows.AddRange(m.Threats.Cast<object>()); rows.AddRange(m.Weaknesses.Cast<object>()); rows.AddRange(m.Controls.Cast<object>()); rows.AddRange(m.AttackSteps.Cast<object>()); rows.AddRange(m.Scenarios.Cast<object>()); rows.AddRange(m.Invariants.Cast<object>()); ListBox list = List(); list.ItemsSource = rows; list.MouseDoubleClick += delegate { if (list.SelectedItem != null) DeepSystems.OpenExternalValue(w, ctx, "SECURITY OBJECT", list.SelectedItem, "ATLAS › SECΩ › " + (m.Name ?? m.Id)); }; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void OpenInventory(Window owner, string title, Func<SecurityModel, List<object>> select) { SecurityModel m = ChooseModel(owner); if (m != null) OpenCollection(owner, title, select(m), "Double-click descent is available from the model registry; this chamber presents the authoritative retained inventory."); }
        private static void OpenAccessLab(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityIdentity subject = ChooseObject(owner, "SELECT SUBJECT", "Choose an identity or group.", m.Identities.Cast<object>().ToList()) as SecurityIdentity; if (subject == null) return; SecurityAsset resource = ChooseObject(owner, "SELECT RESOURCE", "Choose a defended resource.", m.Assets.Cast<object>().ToList()) as SecurityAsset; if (resource == null) return; string action = Prompt(owner, "ACTION", "Action to decide (READ, WRITE, APPROVE, ADMIN, RECOVER or a modeled action):", "READ"); if (action == null) return; SecurityAccessDecision decision = SecurityKernel.DecideAccess(m, subject.Id, resource.Id, action.Trim().ToUpperInvariant()); SecurityAccessArtifact artifact = new SecurityAccessArtifact { Id = Id("access"), ModelId = m.Id, CreatedUtc = Now(), Decision = decision }; Store.AccessDecisions.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "ACCESS_DECISION", artifact.Id, decision.ToString(), SecurityKernel.Fingerprint(m), decision.CertificateHash); OpenCollection(owner, "AUTHORIZATION DECISION", new List<object> { decision }.Concat(decision.MatchingPermissionIds.Select(x => (object)("MATCH   ·   " + x))).ToList(), "Default deny, explicit deny override, group closure and expiry are evaluated deterministically."); }
        private static void RunEntitlements(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityEntitlementAssessment x = SecurityKernel.AssessEntitlements(m); SecurityEntitlementArtifact a = new SecurityEntitlementArtifact { Id = Id("entitlement"), ModelId = m.Id, CreatedUtc = Now(), Assessment = x }; Store.EntitlementAssessments.Insert(0, a); Save(ctx); AppendLedger(ctx, "ENTITLEMENT_ASSESSMENT", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.Findings.Cast<object>()); OpenCollection(owner, "ENTITLEMENT OBSERVATORY", rows, "Privilege, toxic combinations, inactive grants, wildcard scope, factor assurance and reference-rotation debt."); }
        private static void RunAttackGraph(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityScenario s = ChooseScenario(owner, m); SecurityAttackGraphResult x = SecurityKernel.BuildAttackGraph(m, s); SecurityAttackGraphArtifact a = new SecurityAttackGraphArtifact { Id = Id("attack-graph"), ModelId = m.Id, CreatedUtc = Now(), Result = x }; Store.AttackGraphs.Insert(0, a); Save(ctx); AppendLedger(ctx, "ATTACK_GRAPH", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.CrownJewelRoutes.Cast<object>()); rows.AddRange(x.Edges.Cast<object>()); OpenCollection(owner, "ATTACK-GRAPH OBSERVATORY", rows, "Abstract state transitions attenuated by active controls. This is bounded defensive reasoning, never a live procedure."); }
        private static void OpenPrivilegePaths(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityIdentity i = ChooseObject(owner, "IDENTITY", "Choose the identity whose effective reach should be explained.", m.Identities.Cast<object>().ToList()) as SecurityIdentity; if (i == null) return; List<object> rows = new List<object>(); foreach (SecurityAsset a in m.Assets) foreach (string action in new[] { "READ", "WRITE", "APPROVE", "ADMIN", "RECOVER" }) { SecurityAccessDecision d = SecurityKernel.DecideAccess(m, i.Id, a.Id, action); if (Eq(d.Decision, "ALLOW") || a.CrownJewel) rows.Add(d); } OpenCollection(owner, "PRIVILEGE-PATH LAB", rows, "Allowed reach plus every crown-jewel denial, with effective subjects and matching policy certificates."); }
        private static void RunBlastRadius(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> seeds = m.Identities.Cast<object>().ToList(); seeds.AddRange(m.Assets.Cast<object>()); object seed = ChooseObject(owner, "ASSUMED COMPROMISE", "Choose one abstract seed identity or asset.", seeds); string id = SubjectId(seed); if (String.IsNullOrWhiteSpace(id)) return; SecurityScenario s = ChooseScenario(owner, m); SecurityBlastRadiusResult x = SecurityKernel.BlastRadius(m, id, s); SecurityBlastRadiusArtifact a = new SecurityBlastRadiusArtifact { Id = Id("blast-radius"), ModelId = m.Id, CreatedUtc = Now(), Result = x }; Store.BlastRadii.Insert(0, a); Save(ctx); AppendLedger(ctx, "BLAST_RADIUS", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.Items.Cast<object>()); OpenCollection(owner, "BLAST-RADIUS TELESCOPE", rows, "Bounded propagation over dependencies, directional trust and abstract state transitions."); }
        private static void RunSegmentation(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> entities = m.Identities.Cast<object>().ToList(); entities.AddRange(m.Assets.Cast<object>()); object source = ChooseObject(owner, "SOURCE", "Choose an assumed entry entity.", entities); object target = ChooseObject(owner, "TARGET", "Choose a protected target.", m.Assets.Where(q => q.CrownJewel).Cast<object>().ToList()); string s = SubjectId(source), t = SubjectId(target); if (String.IsNullOrWhiteSpace(s) || String.IsNullOrWhiteSpace(t)) return; SecuritySegmentationCut x = SecurityKernel.FindSegmentationCut(m, s, t); SecuritySegmentationArtifact a = new SecuritySegmentationArtifact { Id = Id("segmentation"), ModelId = m.Id, CreatedUtc = Now(), Cut = x }; Store.SegmentationCuts.Insert(0, a); Save(ctx); AppendLedger(ctx, "SEGMENTATION_CUT", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.BoundaryIds.Select(y => (object)("BOUNDARY   ·   " + y))); rows.AddRange(x.RecommendedControlIds.Select(y => (object)y)); OpenCollection(owner, "SEGMENTATION MIN-CUT", rows, "Minimum abstract transition/trust boundary separating source and target."); }
        private static void RunCoverage(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityCoverageResult x = SecurityKernel.AssessCoverage(m); SecurityCoverageArtifact a = new SecurityCoverageArtifact { Id = Id("coverage"), ModelId = m.Id, CreatedUtc = Now(), Result = x }; Store.CoverageAssessments.Insert(0, a); Save(ctx); AppendLedger(ctx, "CONTROL_COVERAGE", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.Rows.Cast<object>()); OpenCollection(owner, "CONTROL-COVERAGE MATRIX", rows, "Prevent/detect/respond/recover coverage and independence for every threat and crown jewel."); }
        private static void OpenDefenseDepth(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityCoverageResult x = SecurityKernel.AssessCoverage(m); List<object> rows = x.Rows.OrderBy(y => y.Independence).ThenBy(y => y.ControlIds.Count).Cast<object>().ToList(); OpenCollection(owner, "DEFENSE-IN-DEPTH CHAMBER", rows, "Weakest independence and single-control dependencies rise first."); }
        private static void OpenDetection(Window owner) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> rows = m.Controls.Where(x => Eq(x.Phase, "DETECT")).OrderBy(x => x.DetectionLatencyMinutes).Cast<object>().ToList(); OpenCollection(owner, "DETECTION ENGINEERING ORBIT", rows, "Modeled detection coverage, evidence strength and latency; no live telemetry access."); }
        private static void RunRisk(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityScenario s = ChooseScenario(owner, m); SecurityRiskRegister x = SecurityKernel.AssessRisk(m, s); SecurityRiskArtifact a = new SecurityRiskArtifact { Id = Id("risk"), ModelId = m.Id, CreatedUtc = Now(), Register = x }; Store.RiskRegisters.Insert(0, a); Save(ctx); AppendLedger(ctx, "RISK_REGISTER", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.Rows.Cast<object>()); OpenCollection(owner, "RESIDUAL-RISK REGISTER", rows, "Inherent risk, independent-control reduction, residual band, uncertainty and tail concentration."); }
        private static void OpenSecurityEconomics(Window owner) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> rows = m.Controls.Where(x => x != null).Select(x => new SecurityControlEconomicsRow { ControlId = x.Id, Name = x.Name, AnnualCost = x.AnnualCost, DefensiveUtility = x.Effectiveness * x.Coverage * (0.25 + 0.75 * x.Independence), UtilityPerCost = x.Effectiveness * x.Coverage * (0.25 + 0.75 * x.Independence) / Math.Max(1, x.AnnualCost) }).OrderByDescending(x => x.UtilityPerCost).Cast<object>().ToList(); OpenCollection(owner, "SECURITY ECONOMICS", rows, "Modeled defensive utility per annualized cost. This ranks hypotheses; it does not authorize procurement."); }
        private static void RunIncident(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; SecurityScenario s = ChooseScenario(owner, m); SecurityIncidentPlan x = SecurityKernel.PlanIncident(m, s); SecurityIncidentArtifact a = new SecurityIncidentArtifact { Id = Id("incident"), ModelId = m.Id, CreatedUtc = Now(), Plan = x }; Store.IncidentPlans.Insert(0, a); Save(ctx); AppendLedger(ctx, "INCIDENT_PLAN", a.Id, x.ToString(), SecurityKernel.Fingerprint(m), x.CertificateHash); List<object> rows = new List<object> { x }; rows.AddRange(x.Timeline.Cast<object>()); rows.AddRange(x.Actions.Cast<object>()); OpenCollection(owner, "INCIDENT COMMAND THEATER", rows, "Hash-chained synthetic timeline and plan-only containment actions. Independent authorization is always required outside YOMI."); }
        private static void OpenContainment(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> entities = m.Identities.Cast<object>().ToList(); entities.AddRange(m.Assets.Cast<object>()); object selected = ChooseObject(owner, "AFFECTED ENTITY", "Choose one assumed affected entity.", entities); if (selected == null) return; SecurityRiskRegister risk = SecurityKernel.AssessRisk(m, null); IList<SecurityContainmentAction> rows = SecurityKernel.PlanContainment(m, new[] { SubjectId(selected) }, risk); OpenCollection(owner, "CONTAINMENT PLANNER", rows.Cast<object>().ToList(), "Every row is SIMULATION_PLAN_ONLY, evidence preserving where possible, and requires external human authorization."); }
        private static void OpenRecovery(Window owner) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> rows = new List<object>(); foreach (SecurityAsset x in m.Assets.Where(q => q.CrownJewel).OrderByDescending(x => x.Criticality)) { rows.Add(x); foreach (string d in x.DependencyIds) rows.Add("DEPENDENCY   ·   " + x.Id + " requires " + d); } rows.Add("TARGET   ·   recovery " + Param(m, "recovery_target_minutes", 240).ToString("0", CultureInfo.InvariantCulture) + " minutes"); rows.Add("INVARIANT   ·   preserve evidence before destructive remediation"); rows.Add("INVARIANT   ·   restore from provenance-verified known-good reference"); OpenCollection(owner, "RECOVERY & CONTINUITY", rows, "Crown-jewel criticality, dependency order and declared recovery targets."); }
