        private static void OpenConstruction(Window owner, DeepSystemsContext ctx)
        {
            SecurityModel m = ChooseModel(owner); if (m == null) return; Window w = W(owner, "YOMI · SECURITY MODEL CONSTRUCTION", 1200, 760); DockPanel root = Shell("MODEL CONSTRUCTION DOCK", "Bounded metadata construction only. Secret material is rejected; all attack steps are abstract non-executable transitions."); WrapPanel p = new WrapPanel();
            p.Children.Add(Btn("ADD ZONE", delegate { string raw = Prompt(w, "ADD ZONE", "id | name | kind | parent id | classification | assurance", "zone-new | New Trust Zone | TRUST_ZONE | zone-internal | INTERNAL | 0.70"); string[] f = Fields(raw); if (f.Length >= 2) { m.Zones.Add(new SecurityZone { Id = Key(f[0]), Name = f[1], Kind = At(f, 2, "TRUST_ZONE"), ParentId = At(f, 3, ""), Classification = At(f, 4, "INTERNAL"), Assurance = Number(At(f, 5, "0.7"), 0.7) }); CommitModel(ctx, m, "ZONE_ADDED", f[0]); } }));
            p.Children.Add(Btn("ADD ASSET", delegate { string raw = Prompt(w, "ADD ASSET", "id | name | kind | zone | crown true/false | C | I | A | value | exposure", "asset-new | New Service | SERVICE | zone-app | false | 0.6 | 0.7 | 0.8 | 0.7 | 0.2"); string[] f = Fields(raw); if (f.Length >= 4) { m.Assets.Add(new SecurityAsset { Id = Key(f[0]), Name = f[1], Kind = At(f, 2, "SERVICE"), ZoneId = At(f, 3, "zone-app"), CrownJewel = Bool(At(f, 4, "false"), false), Confidentiality = Number(At(f, 5, "0.5"), 0.5), Integrity = Number(At(f, 6, "0.5"), 0.5), Availability = Number(At(f, 7, "0.5"), 0.5), BusinessValue = Number(At(f, 8, "0.5"), 0.5), Exposure = Number(At(f, 9, "0.2"), 0.2) }); CommitModel(ctx, m, "ASSET_ADDED", f[0]); } }));
            p.Children.Add(Btn("ADD IDENTITY", delegate { string raw = Prompt(w, "ADD IDENTITY", "id | name | kind | home zone | privileged | assurance | groups comma-separated | factors comma-separated", "identity-new | New Identity | HUMAN | zone-internal | false | 0.70 | group-workforce | FACTOR_A,FACTOR_B"); string[] f = Fields(raw); if (f.Length >= 3) { SecurityIdentity x = new SecurityIdentity { Id = Key(f[0]), Name = f[1], Kind = At(f, 2, "HUMAN"), HomeZoneId = At(f, 3, "zone-internal"), Privileged = Bool(At(f, 4, "false"), false), Assurance = Number(At(f, 5, "0.7"), 0.7) }; x.GroupIds.AddRange(TokensList(At(f, 6, ""))); x.FactorKinds.AddRange(TokensList(At(f, 7, ""))); m.Identities.Add(x); CommitModel(ctx, m, "IDENTITY_ADDED", f[0]); } }));
            p.Children.Add(Btn("ADD PERMISSION", delegate { string raw = Prompt(w, "ADD PERMISSION", "id | subject | resource | action | ALLOW/DENY | JIT true/false | expiry UTC", "permission-new | group-workforce | asset-new | READ | ALLOW | false |"); string[] f = Fields(raw); if (f.Length >= 5) { m.Permissions.Add(new SecurityPermission { Id = Key(f[0]), SubjectId = At(f, 1, ""), ResourceId = At(f, 2, ""), Action = At(f, 3, "READ").ToUpperInvariant(), Effect = At(f, 4, "DENY").ToUpperInvariant(), JustInTime = Bool(At(f, 5, "false"), false), ExpiresUtc = At(f, 6, "") }); CommitModel(ctx, m, "PERMISSION_ADDED", f[0]); } }));
            p.Children.Add(Btn("ADD CONTROL", delegate { string raw = Prompt(w, "ADD CONTROL", "id | name | family | phase | target | threat | effect | coverage | independence | annual cost", "control-new | New Defense | PROTECT | PREVENT | asset-new | * | 0.60 | 0.80 | 0.70 | 10000"); string[] f = Fields(raw); if (f.Length >= 5) { m.Controls.Add(new SecurityControl { Id = Key(f[0]), Name = f[1], Family = At(f, 2, "PROTECT"), Phase = At(f, 3, "PREVENT").ToUpperInvariant(), TargetId = At(f, 4, "*"), ThreatId = At(f, 5, "*"), Effectiveness = Number(At(f, 6, "0.5"), 0.5), Coverage = Number(At(f, 7, "0.5"), 0.5), Independence = Number(At(f, 8, "0.5"), 0.5), AnnualCost = Number(At(f, 9, "0"), 0) }); CommitModel(ctx, m, "CONTROL_ADDED", f[0]); } }));
            p.Children.Add(Btn("ADD ABSTRACT STEP", delegate { string raw = Prompt(w, "ADD ABSTRACT TRANSITION", "id | name | source entity | target entity | weakness | probability | effort | control ids comma-separated", "step-new | Abstract transition | identity-new | asset-new | weakness-new | 0.20 | 0.70 | control-new"); string[] f = Fields(raw); if (f.Length >= 4) { SecurityAttackStep x = new SecurityAttackStep { Id = Key(f[0]), Name = f[1], SourceEntityId = At(f, 2, ""), TargetEntityId = At(f, 3, ""), RequiredWeaknessId = At(f, 4, ""), BaseProbability = Number(At(f, 5, "0.2"), 0.2), Effort = Number(At(f, 6, "0.5"), 0.5) }; x.MitigatingControlIds.AddRange(TokensList(At(f, 7, ""))); m.AttackSteps.Add(x); CommitModel(ctx, m, "ABSTRACT_STEP_ADDED", f[0]); } }));
            p.Children.Add(Btn("MODEL VALIDATION", delegate { OpenCollection(w, "MODEL VALIDATION", SecurityKernel.Validate(m).Cast<object>().ToList(), "The model is not executed; this is source-side referential and safety analysis."); })); root.Children.Add(new ScrollViewer { Content = p, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }); w.Content = root; w.Show();
        }

        private static void ForkModel(Window owner, DeepSystemsContext ctx) { SecurityModel m = ChooseModel(owner); if (m != null) ForkSpecific(owner, ctx, m); }
        private static void ForkSpecific(Window owner, DeepSystemsContext ctx, SecurityModel parent) { string name = Prompt(owner, "FORK FORTRESS", "Name for the counterfactual child:", (parent.Name ?? "Fortress") + " · counterfactual"); if (name == null) return; SecurityModel child = Json.Deserialize<SecurityModel>(Json.Serialize(parent)); string parentFp = SecurityKernel.Fingerprint(parent); child.ParentModelId = parent.Id; child.Id = Id("security-model"); child.Name = name; child.Revision = parent.Revision + 1; child.CreatedUtc = child.UpdatedUtc = Now(); child.SourceKind = "FORTRESS_FORK"; child.SourceId = parent.Id; child.SourceFingerprint = parentFp; child.Status = "ACTIVE"; Store.Models.Insert(0, child); Save(ctx); AppendLedger(ctx, "MODEL_FORK", child.Id, "Counterfactual child forked from " + parent.Id + ".", SecurityKernel.Fingerprint(child), parentFp); OpenModel(owner, ctx, child, WorldKernel.ExternalIndex(ctx, false)); }
        private static void OpenCapsules(Window owner, DeepSystemsContext ctx) { Window w = W(owner, "YOMI · SECURITY PREREGISTRATION CAPSULES", 1280, 820); DockPanel root = Shell("PREREGISTRATION CAPSULES", "Freeze question, worlds, metrics, bounds, assumptions and exact model fingerprint before generating outcomes."); Button create = Btn("FREEZE NEW CAPSULE", delegate { SecurityModel m = ChooseModel(w); if (m == null) return; string name = Prompt(w, "CAPSULE NAME", "Name:", "Crown-jewel resilience preregistration"); if (name == null) return; string question = PromptLarge(w, "QUESTION & COMMITMENTS", "Question | scenario ids | metrics | bounds | assumptions", "Can the modeled fortress prevent or contain crown-jewel reach? | nominal,credential-misuse,compound | residual risk,crown reach,MTTD,MTTC | 4096 states; depth 16; no live execution | synthetic abstractions; declared control effectiveness"); string[] f = Fields(question); SecurityExpeditionCapsule c = new SecurityExpeditionCapsule { Id = Id("security-capsule"), ModelId = m.Id, Name = name, Question = At(f, 0, ""), ScenarioIds = At(f, 1, ""), Metrics = At(f, 2, ""), Bounds = At(f, 3, ""), Assumptions = At(f, 4, ""), ModelFingerprint = SecurityKernel.Fingerprint(m), CreatedUtc = Now(), Status = "FROZEN" }; c.CertificateHash = HashText(c.ModelId + "|" + c.Name + "|" + c.Question + "|" + c.ScenarioIds + "|" + c.Metrics + "|" + c.Bounds + "|" + c.Assumptions + "|" + c.ModelFingerprint); Store.Capsules.Insert(0, c); Save(ctx); AppendLedger(ctx, "CAPSULE_FROZEN", c.Id, c.Question, c.ModelFingerprint, c.CertificateHash); OpenCapsules(w, ctx); }); DockPanel.SetDock(create, Dock.Top); root.Children.Add(create); ListBox list = List(); list.ItemsSource = Store.Capsules; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void OpenBaselines(Window owner, DeepSystemsContext ctx) { Window w = W(owner, "YOMI · IMMUTABLE SECURITY BASELINES", 1280, 820); DockPanel root = Shell("IMMUTABLE BASELINES", "Seal the latest campaign and coverage certificates against the exact model fingerprint."); Button create = Btn("SEAL BASELINE", delegate { SecurityModel m = ChooseModel(w); if (m == null) return; SecurityCampaignArtifact campaign = Store.Campaigns.FirstOrDefault(x => Eq(x.ModelId, m.Id)); SecurityCoverageArtifact coverage = Store.CoverageAssessments.FirstOrDefault(x => Eq(x.ModelId, m.Id)); if (campaign == null || coverage == null) { MessageBox.Show(w, "Create a campaign and coverage assessment first.", "YOMI", MessageBoxButton.OK, MessageBoxImage.Information); return; } string name = Prompt(w, "BASELINE NAME", "Name:", (m.Name ?? "Fortress") + " · sealed baseline"); if (name == null) return; SecurityBaseline b = new SecurityBaseline { Id = Id("security-baseline"), ModelId = m.Id, Name = name, ModelFingerprint = SecurityKernel.Fingerprint(m), CampaignArtifactId = campaign.Id, CoverageArtifactId = coverage.Id, ResidualRisk = campaign.Result.WeightedResidualRisk, Resilience = campaign.Result.ResilienceScore, CreatedUtc = Now(), Status = "IMMUTABLE" }; b.CertificateHash = HashText(b.ModelId + "|" + b.Name + "|" + b.ModelFingerprint + "|" + b.CampaignArtifactId + "|" + b.CoverageArtifactId + "|" + b.ResidualRisk.ToString("R", CultureInfo.InvariantCulture) + "|" + b.Resilience.ToString("R", CultureInfo.InvariantCulture)); Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_SEALED", b.Id, b.ToString(), b.ModelFingerprint, b.CertificateHash); OpenBaselines(w, ctx); }); DockPanel.SetDock(create, Dock.Top); root.Children.Add(create); ListBox list = List(); list.ItemsSource = Store.Baselines; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void OpenDossiers(Window owner, DeepSystemsContext ctx) { Window w = W(owner, "YOMI · SECURITY DECISION DOSSIERS", 1280, 820); DockPanel root = Shell("DECISION DOSSIERS", "Bind a decision to artifacts, evidence, assumptions and accepted residual risk."); Button create = Btn("CREATE DOSSIER", delegate { SecurityModel m = ChooseModel(w); if (m == null) return; string raw = PromptLarge(w, "DECISION DOSSIER", "title | decision | rationale | residual risk | artifact ids | evidence node ids | assumptions", "Fortress reinforcement decision | PRIORITIZE DETECTION AND SEGMENTATION | Coverage gaps and crown paths dominate expected loss | Residual risk is accepted only within declared threshold | latest campaign,coverage,graph,incident | linked world evidence | simulation-only; independent authorization required"); string[] f = Fields(raw); if (raw == null) return; SecurityDecisionDossier d = new SecurityDecisionDossier { Id = Id("security-dossier"), ModelId = m.Id, Title = At(f, 0, "Security decision"), Decision = At(f, 1, "UNDECIDED"), Rationale = At(f, 2, ""), ResidualRisk = At(f, 3, ""), ArtifactIds = At(f, 4, ""), EvidenceNodeIds = At(f, 5, ""), Assumptions = At(f, 6, ""), CreatedUtc = Now(), Status = "DRAFT" }; d.CertificateHash = HashText(d.ModelId + "|" + d.Title + "|" + d.Decision + "|" + d.Rationale + "|" + d.ResidualRisk + "|" + d.ArtifactIds + "|" + d.EvidenceNodeIds + "|" + d.Assumptions); Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Decision, SecurityKernel.Fingerprint(m), d.CertificateHash); OpenDossiers(w, ctx); }); DockPanel.SetDock(create, Dock.Top); root.Children.Add(create); ListBox list = List(); list.ItemsSource = Store.Dossiers; root.Children.Add(list); w.Content = root; w.Show(); }
        private static void OpenSourceDrift(Window owner) { List<object> rows = new List<object>(); foreach (SecurityModel m in Store.Models.Where(x => !Eq(x.SourceKind, "NATIVE") && !Eq(x.SourceKind, "FORTRESS_FORK"))) rows.Add(new SecuritySourceDriftRow { ModelId = m.Id, SourceKind = m.SourceKind, SourceId = m.SourceId, CapturedFingerprint = m.SourceFingerprint, Status = "CAPTURED SOURCE FINGERPRINT · open upstream peer to compare current state" }); OpenCollection(owner, "SOURCE-DRIFT RADAR", rows, "The Fortress never silently refreshes a projection. A changed upstream fingerprint creates a new fork, preserving both histories."); }
        private static void OpenLedger(Window owner, DeepSystemsContext ctx) { List<SecurityFortressLedgerRecord> rows = ReadLedger(ctx, 32768); List<object> display = new List<object> { VerifyLedger(rows) }; display.AddRange(rows.OrderByDescending(x => x.Sequence).Cast<object>()); OpenCollection(owner, "TAMPER-EVIDENT FORTRESS LEDGER", display, "Each record includes the prior hash, model fingerprint and artifact certificate."); }
        private static void OpenHadal(Window owner) { SecurityModel m = ChooseModel(owner); if (m == null) return; List<object> rows = new List<object> { m }; rows.AddRange(m.Assets.OrderByDescending(x => x.CrownJewel).Cast<object>()); rows.AddRange(m.Zones.Cast<object>()); rows.AddRange(m.Identities.Cast<object>()); rows.AddRange(m.Permissions.Cast<object>()); rows.AddRange(m.TrustRelations.Cast<object>()); rows.AddRange(m.Threats.Cast<object>()); rows.AddRange(m.AttackSteps.Cast<object>()); rows.AddRange(m.Controls.Cast<object>()); rows.AddRange(Store.IncidentPlans.Where(x => Eq(x.ModelId, m.Id)).Cast<object>()); OpenCollection(owner, "HADAL SECURITY DESCENT", rows, "Asset → zone → identity → permission → trust → threat → transition → control → incident → evidence without flattening provenance."); }
