            m.Invariants.AddRange(new[] { new SecurityInvariant { Id = "inv-deny", Name = "Explicit deny always overrides allow", Kind = "DENY_OVERRIDES", Severity = "CRITICAL" }, new SecurityInvariant { Id = "inv-disabled", Name = "Inactive identities retain no active allow grants", Kind = "NO_DISABLED_GRANTS", Severity = "CRITICAL" }, new SecurityInvariant { Id = "inv-sod", Name = "Change and approval duties remain separated", Kind = "SEPARATION_OF_DUTIES", Severity = "HIGH" }, new SecurityInvariant { Id = "inv-crown-detect", Name = "Every crown jewel has modeled detection", Kind = "CROWN_DETECTION", Severity = "CRITICAL" }, new SecurityInvariant { Id = "inv-workforce-admin", Name = "Workforce group cannot administer control plane", Kind = "ACCESS_DENIED", SubjectId = "group-workforce", ResourceId = "asset-admin-console", Action = "ADMIN", Severity = "CRITICAL" } });
            m.Assumptions.Add("All adversaries, weaknesses, transitions and observations are synthetic abstractions for defensive analysis."); m.Assumptions.Add("No real hostname, address, credential, secret, vulnerability probe, exploit instruction, command or execution authority is represented."); m.Assumptions.Add("Control effectiveness and threat likelihood are declared hypotheses, not empirical guarantees."); m.Assumptions.Add("Containment actions are plans only and require separate approved authority, evidence handling and change control."); return m;
        }

        private static SecurityZone Zone(string id,string name,string kind,string parent,string classification,double assurance) { return new SecurityZone { Id=id,Name=name,Kind=kind,ParentId=parent,Classification=classification,Assurance=assurance }; }
        private static SecurityAsset Asset(string id,string name,string kind,string zone,bool crown,double c,double i,double a,double value,double exposure) { return new SecurityAsset { Id=id,Name=name,Kind=kind,ZoneId=zone,CrownJewel=crown,Confidentiality=c,Integrity=i,Availability=a,BusinessValue=value,Exposure=exposure }; }
        private static void Depend(SecurityModel m,string id,params string[] dependencies) { SecurityAsset x=m.Assets.First(y=>Eq(y.Id,id)); x.DependencyIds.AddRange(dependencies); }
        private static SecurityIdentity Identity(string id,string name,string kind,string zone,bool privileged,double assurance,string groups,string factors) { SecurityIdentity x=new SecurityIdentity { Id=id,Name=name,Kind=kind,HomeZoneId=zone,Privileged=privileged,Assurance=assurance,AssuranceLevel=assurance>=.9?"HIGH":assurance>=.75?"ELEVATED":"STANDARD",LastReviewedUtc=Now() }; x.GroupIds.AddRange(TokensList(groups)); x.FactorKinds.AddRange(TokensList(factors)); return x; }
        private static SecuritySecretReference Secret(string id,string name,string custodian,string asset,string locator,double age,double target,double exposure) { return new SecuritySecretReference { Id=id,Name=name,CustodianIdentityId=custodian,BoundAssetId=asset,ReferenceLocator=locator,AgeDays=age,RotationTargetDays=target,Exposure=exposure }; }
        private static void Permit(SecurityModel m,string id,string subject,string resource,string action,string effect,bool jit) { m.Permissions.Add(new SecurityPermission { Id=id,SubjectId=subject,ResourceId=resource,Action=action,Effect=effect,JustInTime=jit,Source="AEGIS_POLICY" }); }
        private static SecurityTrustRelation Trust(string id,string from,string to,string kind,double strength,bool transitive) { return new SecurityTrustRelation { Id=id,FromId=from,ToId=to,Kind=kind,Strength=strength,Transitive=transitive }; }
        private static SecurityInterface Interface(string id,string name,string asset,string from,string to,string auth,bool encrypted,bool rate,double exposure) { return new SecurityInterface { Id=id,Name=name,AssetId=asset,FromZoneId=from,ToZoneId=to,AuthenticationClass=auth,Encrypted=encrypted,RateLimited=rate,Exposure=exposure }; }
        private static SecurityThreat Threat(string id,string name,string actor,string objective,string tactic,string target,string initial,double capability,double intent,double likelihood,double impact) { return new SecurityThreat { Id=id,Name=name,ActorClass=actor,Objective=objective,TacticClass=tactic,TargetAssetId=target,InitialEntityId=initial,Capability=capability,Intent=intent,Likelihood=likelihood,ImpactMultiplier=impact }; }
        private static SecurityWeakness Weakness(string id,string name,string asset,string kind,double severity,double exploitability,double confidence) { return new SecurityWeakness { Id=id,Name=name,AssetId=asset,Kind=kind,Severity=severity,Exploitability=exploitability,Confidence=confidence }; }
        private static void ControlSet(SecurityModel m,string prefix,string target,string threat,double effect,double coverage,double independence,double detect,double respond,double cost) { m.Controls.Add(new SecurityControl { Id="control-"+prefix+"-prevent",Name=Title(prefix)+" Prevention",Family="PROTECT",Phase="PREVENT",TargetId=target,ThreatId=threat,Effectiveness=effect,Coverage=coverage,Independence=independence,AnnualCost=cost*.4,EvidenceStrength="MODELED_WITH_RATIONALE" }); m.Controls.Add(new SecurityControl { Id="control-"+prefix+"-detect",Name=Title(prefix)+" Detection",Family="DETECT",Phase="DETECT",TargetId=target,ThreatId=threat,Effectiveness=Math.Max(.2,effect-.08),Coverage=Math.Max(.2,coverage-.04),Independence=Math.Min(.98,independence+.04),DetectionLatencyMinutes=detect,AnnualCost=cost*.25,EvidenceStrength="MODELED_WITH_RATIONALE" }); m.Controls.Add(new SecurityControl { Id="control-"+prefix+"-respond",Name=Title(prefix)+" Response",Family="RESPOND",Phase="RESPOND",TargetId=target,ThreatId=threat,Effectiveness=Math.Max(.2,effect-.12),Coverage=Math.Max(.2,coverage-.06),Independence=independence,ResponseLatencyMinutes=respond,AnnualCost=cost*.2,EvidenceStrength="EXERCISE_REQUIRED" }); m.Controls.Add(new SecurityControl { Id="control-"+prefix+"-recover",Name=Title(prefix)+" Recovery",Family="RECOVER",Phase="RECOVER",TargetId=target,ThreatId=threat,Effectiveness=Math.Max(.2,effect-.06),Coverage=Math.Max(.2,coverage-.08),Independence=Math.Min(.98,independence+.06),AnnualCost=cost*.15,EvidenceStrength="EXERCISE_REQUIRED" }); }
        private static void Step(SecurityModel m,string id,string name,string from,string to,string weakness,double p,double effort,string controls) { SecurityAttackStep x=new SecurityAttackStep { Id=id,Name=name,SourceEntityId=from,TargetEntityId=to,RequiredWeaknessId=weakness,BaseProbability=p,Effort=effort,TacticClass="ABSTRACT_DEFENSIVE_TRANSITION",Status="MODELED_ONLY" }; x.MitigatingControlIds.AddRange(TokensList(controls)); m.AttackSteps.Add(x); }
        private static SecurityScenario Scenario(string id,string name,string threats,string initial,string disabled,double lm,double im,double weight) { return new SecurityScenario { Id=id,Name=name,ThreatIds=threats,InitialCompromiseIds=initial,DisabledControlIds=disabled,LikelihoodMultiplier=lm,ImpactMultiplier=im,Weight=weight,MaxStates=4096,MaxDepth=16 }; }

        private static void CommitModel(DeepSystemsContext ctx, SecurityModel m, string evt, string detail) { m.Revision++; m.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, evt, m.Id, detail, SecurityKernel.Fingerprint(m), ""); }
        private static void Ensure(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<SecurityFortressStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<SecurityFortressStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new SecurityFortressStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new SecurityFortressStore(); if (Store.Models == null) Store.Models = new List<SecurityModel>(); if (Store.AccessDecisions == null) Store.AccessDecisions = new List<SecurityAccessArtifact>(); if (Store.EntitlementAssessments == null) Store.EntitlementAssessments = new List<SecurityEntitlementArtifact>(); if (Store.AttackGraphs == null) Store.AttackGraphs = new List<SecurityAttackGraphArtifact>(); if (Store.BlastRadii == null) Store.BlastRadii = new List<SecurityBlastRadiusArtifact>(); if (Store.CoverageAssessments == null) Store.CoverageAssessments = new List<SecurityCoverageArtifact>(); if (Store.RiskRegisters == null) Store.RiskRegisters = new List<SecurityRiskArtifact>(); if (Store.SegmentationCuts == null) Store.SegmentationCuts = new List<SecuritySegmentationArtifact>(); if (Store.IncidentPlans == null) Store.IncidentPlans = new List<SecurityIncidentArtifact>(); if (Store.Campaigns == null) Store.Campaigns = new List<SecurityCampaignArtifact>(); if (Store.AssuranceCases == null) Store.AssuranceCases = new List<SecurityAssuranceArtifact>(); if (Store.Capsules == null) Store.Capsules = new List<SecurityExpeditionCapsule>(); if (Store.Baselines == null) Store.Baselines = new List<SecurityBaseline>(); if (Store.Dossiers == null) Store.Dossiers = new List<SecurityDecisionDossier>(); foreach (SecurityModel m in Store.Models.Where(x => x != null)) SecurityKernel.Normalize(m); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision++; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("security-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void TrimStore() { Store.Models = Store.Models.Where(x=>x!=null).Take(MaxModels).ToList(); Store.AccessDecisions=Store.AccessDecisions.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.EntitlementAssessments=Store.EntitlementAssessments.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.AttackGraphs=Store.AttackGraphs.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.BlastRadii=Store.BlastRadii.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.CoverageAssessments=Store.CoverageAssessments.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.RiskRegisters=Store.RiskRegisters.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.SegmentationCuts=Store.SegmentationCuts.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.IncidentPlans=Store.IncidentPlans.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.Campaigns=Store.Campaigns.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.AssuranceCases=Store.AssuranceCases.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.Capsules=Store.Capsules.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.Baselines=Store.Baselines.Where(x=>x!=null).Take(MaxArtifacts).ToList(); Store.Dossiers=Store.Dossiers.Where(x=>x!=null).Take(MaxArtifacts).ToList(); }
        private static void AtomicWrite(string path,string text) { string temp=path+".next", previous=path+".previous"; File.WriteAllText(temp,text??"",new UTF8Encoding(false)); if(File.Exists(path)){ if(File.Exists(previous))File.Delete(previous); File.Move(path,previous); } File.Move(temp,path); }
        private static void PreserveCorrupt(string path) { try { if(File.Exists(path))File.Copy(path,path+".corrupt-"+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff",CultureInfo.InvariantCulture),true); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot,"adversarial-security-fortress-v1.json"); } private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot,"adversarial-security-ledger-v1.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx,string evt,string subject,string detail,string fingerprint,string certificate) { lock(Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<SecurityFortressLedgerRecord> prior=ReadLedger(ctx,32768); SecurityFortressLedgerRecord last=prior.OrderByDescending(x=>x.Sequence).FirstOrDefault(); SecurityFortressLedgerRecord r=new SecurityFortressLedgerRecord { Schema=1,Sequence=last==null?1:last.Sequence+1,Utc=Now(),Event=Short(evt,120),Subject=Short(subject,512),Detail=Short(detail,MaxLongText),CorrelationId=Store==null?"":Store.LastCommitId,ModelFingerprint=Short(fingerprint,128),CertificateHash=Short(certificate,128),PrevHash=last==null?new string('0',64):last.EntryHash }; r.EntryHash=LedgerHash(r); byte[] bytes=Encoding.UTF8.GetBytes(Json.Serialize(r)+Environment.NewLine); using(FileStream stream=new FileStream(LedgerPath(ctx),FileMode.Append,FileAccess.Write,FileShare.Read,4096,FileOptions.WriteThrough)){stream.Write(bytes,0,bytes.Length);stream.Flush();} } catch { } }
        private static List<SecurityFortressLedgerRecord> ReadLedger(DeepSystemsContext ctx,int cap) { List<SecurityFortressLedgerRecord> rows=new List<SecurityFortressLedgerRecord>(); string path=LedgerPath(ctx); if(!File.Exists(path))return rows; try { foreach(string line in File.ReadLines(path,Encoding.UTF8)){if(String.IsNullOrWhiteSpace(line))continue;SecurityFortressLedgerRecord r=Json.Deserialize<SecurityFortressLedgerRecord>(line);if(r!=null){rows.Add(r);if(rows.Count>cap)rows.RemoveAt(0);}} } catch { } return rows; }
        private static string VerifyLedger(List<SecurityFortressLedgerRecord> rows) { if(rows==null||rows.Count==0)return "EMPTY CHAIN";rows=rows.OrderBy(x=>x.Sequence).ToList();long expected=rows[0].Sequence;string prior=expected==1?new string('0',64):rows[0].PrevHash;foreach(SecurityFortressLedgerRecord row in rows){if(row.Sequence!=expected)return "CHAIN GAP @ "+expected;if(!Eq(row.PrevHash,prior))return "PREV HASH MISMATCH @ "+row.Sequence;if(!Eq(row.EntryHash,LedgerHash(row)))return "ENTRY HASH MISMATCH @ "+row.Sequence;expected++;prior=row.EntryHash;}return "CHAIN VERIFIED · "+rows.Count.ToString(CultureInfo.InvariantCulture)+" RECORDS"; }
        private static string LedgerHash(SecurityFortressLedgerRecord r) { return HashText(r.Schema+"|"+r.Sequence+"|"+(r.Utc??"")+"|"+(r.Event??"")+"|"+(r.Subject??"")+"|"+(r.Detail??"")+"|"+(r.CorrelationId??"")+"|"+(r.ModelFingerprint??"")+"|"+(r.CertificateHash??"")+"|"+(r.PrevHash??"")); }

