        private static SecurityScenario ChooseScenario(Window owner,SecurityModel m) { List<object> rows=new List<object>{"BASE / ALL ACTIVE CONTROLS"};rows.AddRange(m.Scenarios.Cast<object>());return ChooseObject(owner,"SCENARIO WORLD","Choose a synthetic adversarial world or the base world.",rows) as SecurityScenario; }
        private static string SubjectId(object x) { SecurityAsset a=x as SecurityAsset;if(a!=null)return a.Id;SecurityIdentity i=x as SecurityIdentity;if(i!=null)return i.Id;SecurityZone z=x as SecurityZone;if(z!=null)return z.Id;return ""; }
        private static string Summary() { return Store.Models.Count+" fortresses   ·   "+Store.AccessDecisions.Count+" access decisions   ·   "+Store.EntitlementAssessments.Count+" entitlement audits   ·   "+Store.AttackGraphs.Count+" attack graphs   ·   "+Store.BlastRadii.Count+" blast radii   ·   "+Store.CoverageAssessments.Count+" coverage matrices   ·   "+Store.RiskRegisters.Count+" risk registers   ·   "+Store.IncidentPlans.Count+" incident plans   ·   "+Store.Campaigns.Count+" campaigns   ·   "+Store.AssuranceCases.Count+" assurance cases"; }
        private static string HashObject(object value) { try { return HashText(Json.Serialize(value)); } catch { return HashText(value==null?"NULL":value.ToString()); } }
        private static string HashText(string value) { using(SHA256 h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value??""))).Replace("-","").ToLowerInvariant(); }
        private static bool Eq(string a,string b) { return String.Equals(a??"",b??"",StringComparison.OrdinalIgnoreCase); } private static double Param(SecurityModel m,string key,double fallback){double v;return m.Parameters!=null&&m.Parameters.TryGetValue(key,out v)?v:fallback;}
        private static double Number(string raw,double fallback){double v;return Double.TryParse(raw,NumberStyles.Float,CultureInfo.InvariantCulture,out v)&&!Double.IsNaN(v)&&!Double.IsInfinity(v)?v:fallback;} private static bool Bool(string raw,bool fallback){bool v;return Boolean.TryParse(raw,out v)?v:fallback;}
        private static string[] Fields(string raw){return(raw??"").Split('|');} private static string At(string[] f,int i,string fallback){return f!=null&&i>=0&&i<f.Length?f[i].Trim():fallback;} private static List<string> TokensList(string raw){return(raw??"").Split(new[]{',',';','\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).Where(x=>x.Length>0).Distinct(StringComparer.OrdinalIgnoreCase).ToList();}
        private static string Key(string value){StringBuilder s=new StringBuilder();foreach(char c in(value??"").ToLowerInvariant())if(Char.IsLetterOrDigit(c)||c=='_'||c=='-')s.Append(c);else if(s.Length>0&&s[s.Length-1]!='-')s.Append('-');return s.ToString().Trim('-');} private static string Title(string value){return CultureInfo.InvariantCulture.TextInfo.ToTitleCase((value??"").Replace('-',' ').Replace('_',' '));}
        private static string Short(string value,int cap){value=value??"";cap=Math.Max(1,cap);return value.Length<=cap?value:value.Substring(0,cap-1)+"…";} private static string Id(string prefix){return prefix+"-"+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff",CultureInfo.InvariantCulture)+"-"+Guid.NewGuid().ToString("N").Substring(0,8);} private static string Now(){return DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);}
        private static Brush B(string hex){return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex));} private static Window W(Window owner,string title,double width,double height){return new Window{Title=title,Width=width,Height=height,MinWidth=Math.Min(width,820),MinHeight=Math.Min(height,560),Background=Bg,Foreground=Text,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=owner,FontFamily=new FontFamily("Segoe UI")};}
        private static DockPanel Shell(string title,string subtitle){DockPanel root=new DockPanel{Margin=new Thickness(16)};StackPanel head=new StackPanel{Margin=new Thickness(0,0,0,10)};head.Children.Add(T(title,24,Text,FontWeights.Bold));head.Children.Add(T(subtitle,12,Muted,FontWeights.Normal));DockPanel.SetDock(head,Dock.Top);root.Children.Add(head);return root;} private static TextBlock T(string value,double size,Brush foreground,FontWeight weight){return new TextBlock{Text=value??"",FontSize=size,Foreground=foreground,FontWeight=weight,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,2,0,2)};}
        private static Button Btn(string label,RoutedEventHandler click){Button b=new Button{Content=label,Margin=new Thickness(0,0,8,8),Padding=new Thickness(12,7,12,7),Background=Raised,Foreground=Text,BorderBrush=Border,BorderThickness=new Thickness(1),MinWidth=112};if(click!=null)b.Click+=click;return b;} private static ListBox List(){return new ListBox{Background=Surface,Foreground=Text,BorderBrush=Border,BorderThickness=new Thickness(1),Margin=new Thickness(0,6,6,0),Padding=new Thickness(5),FontFamily=new FontFamily("Cascadia Mono, Consolas")};}
