        private static string Prompt(Window owner,string title,string label,string initial){Window w=W(owner,"YOMI · "+title,760,310);DockPanel root=new DockPanel{Margin=new Thickness(16)};TextBlock cap=T(label,12,Muted,FontWeights.Normal);DockPanel.SetDock(cap,Dock.Top);root.Children.Add(cap);TextBox edit=new TextBox{Text=initial??"",MaxLength=MaxShortText,Margin=new Thickness(0,8,0,10),Background=Surface,Foreground=Text,BorderBrush=Border,Padding=new Thickness(8)};DockPanel.SetDock(edit,Dock.Top);root.Children.Add(edit);WrapPanel buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right};string result=null;buttons.Children.Add(Btn("OK",delegate{result=edit.Text;w.DialogResult=true;}));buttons.Children.Add(Btn("CANCEL",delegate{w.DialogResult=false;}));root.Children.Add(buttons);w.Content=root;bool? accepted=w.ShowDialog();return accepted==true?result:null;}
        private static string PromptLarge(Window owner,string title,string label,string initial){Window w=W(owner,"YOMI · "+title,860,600);DockPanel root=new DockPanel{Margin=new Thickness(16)};TextBlock cap=T(label,12,Muted,FontWeights.Normal);DockPanel.SetDock(cap,Dock.Top);root.Children.Add(cap);TextBox edit=new TextBox{Text=initial??"",MaxLength=MaxLongText,AcceptsReturn=true,AcceptsTab=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,8,0,0),Background=Surface,Foreground=Text,BorderBrush=Border,Padding=new Thickness(10),FontFamily=new FontFamily("Cascadia Mono, Consolas")};WrapPanel buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};string result=null;buttons.Children.Add(Btn("SAVE",delegate{result=edit.Text;w.DialogResult=true;}));buttons.Children.Add(Btn("CANCEL",delegate{w.DialogResult=false;}));DockPanel.SetDock(buttons,Dock.Bottom);root.Children.Add(buttons);root.Children.Add(edit);w.Content=root;bool? accepted=w.ShowDialog();return accepted==true?result:null;}
        private static object ChooseObject(Window owner,string title,string label,IList<object> choices){Window w=W(owner,"YOMI · "+title,820,580);DockPanel root=new DockPanel{Margin=new Thickness(16)};TextBlock cap=T(label,12,Muted,FontWeights.Normal);DockPanel.SetDock(cap,Dock.Top);root.Children.Add(cap);ListBox list=List();list.ItemsSource=choices??new List<object>();if(list.Items.Count>0)list.SelectedIndex=0;WrapPanel buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};object result=null;buttons.Children.Add(Btn("SELECT",delegate{result=list.SelectedItem;w.DialogResult=true;}));buttons.Children.Add(Btn("CANCEL",delegate{w.DialogResult=false;}));list.MouseDoubleClick+=delegate{result=list.SelectedItem;if(result!=null)w.DialogResult=true;};DockPanel.SetDock(buttons,Dock.Bottom);root.Children.Add(buttons);root.Children.Add(list);w.Content=root;bool? accepted=w.ShowDialog();return accepted==true?result:null;}
        private static void OpenCollection(Window owner,string title,IList<object> rows,string subtitle){Window w=W(owner,"YOMI · "+title,1320,860);DockPanel root=Shell(title,subtitle);ListBox list=List();list.ItemsSource=rows??new List<object>();root.Children.Add(list);w.Content=root;w.Show();} private static void OpenSelectable(Window owner,string title,IList<object> rows,string subtitle,Action<object> open){Window w=W(owner,"YOMI · "+title,1320,860);DockPanel root=Shell(title,subtitle);ListBox list=List();list.ItemsSource=rows??new List<object>();list.MouseDoubleClick+=delegate{if(list.SelectedItem!=null&&open!=null)open(list.SelectedItem);};root.Children.Add(list);w.Content=root;w.Show();}
